import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {simulateWorkforce, workforceHistoricalCheck, weightedEnrolment, constructionTimeline, normalizeCapacitySelection, validateCapacityData, simulateCapacity} from '../capacity-model.mjs';

// Independent literal transcription checked against CIHI Table 3a source XML,
// not generated by the production extractor or production model helpers.
const stock = [34992,35448,35691,35907,36394,36288,36302,37202,42694,44799];
const inflow = [2467,2609,2406,2459,2588,2390,2591,3508,7783,5436];
const outflow = [2153,2163,2243,2101,2496,2577,2608,2291,3331,null];
const renewals = [32525,32839,33285,33448,33806,33898,33711,33694,34911,39363];
const root = new URL('../', import.meta.url);
const research = JSON.parse(await readFile(new URL('capacity-workforce-research.json', root),'utf8'));
const rn = research.registeredNurses;
const near = (actual, expected, label) => assert.ok(Math.abs(actual-expected)<1e-7, `${label}: ${actual} != ${expected}`);
assert.deepEqual(rn.history.map(r=>r.year),[2016,2017,2018,2019,2020,2021,2022,2023,2024,2025]);
for (const [field,values] of Object.entries({supply:stock,inflow,outflow,renewal:renewals})) {
  assert.deepEqual(rn.history.map(r=>r[field]), values, `source observations: ${field}`);
}
for(let j=1;j<stock.length;j++) {
  assert.equal(stock[j-1]-outflow[j-1]+inflow[j],stock[j],`stock-flow alignment ${2016+j}`);
  assert.equal(stock[j-1]-outflow[j-1],renewals[j],`renewals ${2016+j}`);
}
const holdout=rn.validation.retrospectiveHoldout;
assert.deepEqual(holdout.trainingInflowYears,[2016,2017,2018,2019,2020]);
assert.deepEqual(holdout.trainingOutflowYears,[2016,2017,2018,2019]);
assert.deepEqual(holdout.holdoutYears,[2021,2022,2023,2024,2025]);
assert.match(holdout.label,/not a real-time/);
assert.match(rn.validation.accountingReplay.label,/not forecast/);
near(holdout.annualEntrants,2505.8,'training inflow');
near(holdout.outflowRate,8660/142038,'training outflow rate');

// Closed-form geometric-stock solution independently checks the iterative
// extractor, using only pre-holdout literals. Future stocks/flows never enter it.
const survival=1-8660/142038;
const predicted=Array.from({length:5},(_,index)=>{
  const horizon=index+1;
  return stock[4]*survival**horizon+2505.8*(1-survival**horizon)/(1-survival);
});
const observed=stock.slice(5);
const metrics=(values)=>{
  const errors=values.map((v,j)=>v-observed[j]);
  return {
    n:5,
    mae:errors.reduce((s,v)=>s+Math.abs(v),0)/5,
    bias:errors.reduce((s,v)=>s+v,0)/5,
    rmse:Math.sqrt(errors.reduce((s,v)=>s+v*v,0)/5),
    mapePercent:errors.reduce((s,v,j)=>s+Math.abs(v)/observed[j]*100,0)/5,
  };
};
const benchmarkSets=[
  [holdout,predicted],
  [holdout.noChangeBaseline,Array(5).fill(36394)],
  [holdout.linearDriftBaseline,Array.from({length:5},(_,j)=>36394+350.5*(j+1))],
];
for(const [record,values] of benchmarkSets) {
  record.rows.forEach((row,j)=>{
    assert.equal(row.year,2021+j);
    assert.equal(row.actual,observed[j]);
    near(row.predicted,values[j],`holdout prediction ${row.year}`);
  });
  for(const [key,value] of Object.entries(metrics(values))) near(record.metrics[key],value,`holdout ${key}`);
}
near(rn.model.baselineAnnualEntrants,16727/3,'recent-scenario entrants');
near(rn.model.baselineOutflowRate,8230/116198,'recent-scenario exit rate');
assert.equal(rn.model.originSupply,44799);
assert.ok(holdout.metrics.mae>holdout.linearDriftBaseline.metrics.mae,'stock-flow does not beat linear drift');

const productionHistory=workforceHistoricalCheck(rn.history);
productionHistory.rows.forEach((row,j)=>near(row.predicted,predicted[j],`production holdout ${row.year}`));
near(productionHistory.model.mae,metrics(predicted).mae,'production MAE');
near(productionHistory.drift.mae,2608.7,'production drift baseline');
near(productionHistory.replay.mae,0,'production replay');
const changedFuture=structuredClone(rn.history);
changedFuture.filter(r=>r.year>2020).forEach(r=>{r.supply*=1.7;r.inflow*=2.3;if(r.outflow!==null)r.outflow*=1.9;});
changedFuture.find(r=>r.year===2020).outflow=9999; // Requires 2021 registrations: unavailable to 2020 model.
const futureInsensitive=workforceHistoricalCheck(changedFuture);
futureInsensitive.rows.forEach((row,j)=>near(row.predicted,predicted[j],`no future-observation leakage ${row.year}`));

const baselineSurvival=1-8230/116198, entrantAverage=16727/3;
const geometric=(s,n)=>Math.abs(1-s)<1e-12?n:(1-s**n)/(1-s);
const baselineFinal=44799*baselineSurvival**5+entrantAverage*geometric(baselineSurvival,5);
const base=simulateWorkforce(rn.history,{years:5});
near(base.last.baseline,baselineFinal,'production baseline closed form');
near(base.additional,0,'zero-change scenario identity');
const changed=simulateWorkforce(rn.history,{years:5,extraEntrants:1000,retentionPp:1,delayYears:1});
const improvedSurvival=baselineSurvival+.01;
const expectedFinal=44799*improvedSurvival**5+entrantAverage*geometric(improvedSurvival,5)+1000*geometric(improvedSurvival,4);
near(changed.last.scenario,expectedFinal,'scenario closed form includes delayed entrants and retained added cohort');
near(changed.recruitmentOnlyGain,1000*geometric(baselineSurvival,4),'recruitment gain independent solution');
near(changed.recruitmentOnlyGain+changed.retentionAndInteractionGain,changed.additional,'decomposition sums');
assert.deepEqual(changed.rows.map(r=>r.extraEntries),[0,0,1000,1000,1000,1000]);
const longDelay=simulateWorkforce(rn.history,{years:5,extraEntrants:1000,retentionPp:1,delayYears:3});
assert.ok(longDelay.last.scenario<changed.last.scenario,'longer wait reduces ending supply');
assert.deepEqual(rn.history.map(r=>r.supply),stock,'simulation preserves observed history');
for(const raw of [null,{}, {extraEntrants:Infinity,retentionPp:NaN,delayYears:-999,years:999},{extraEntrants:'junk',retentionPp:999,delayYears:Infinity}]) {
  const normalized=normalizeCapacitySelection(raw);
  for(const v of Object.values(normalized)) if(typeof v==='number') assert.ok(Number.isFinite(v));
}

// Literal values visually checked against three CBE source schedules; funding
// weights are a separate arithmetic question from forecast accuracy.
near(weightedEnrolment(115102,120654,127706,'previous'),123069.6,'2023 old rule');
near(weightedEnrolment(115102,120654,127706,'current'),125590.4,'2023 new-rule counterfactual');
near(weightedEnrolment(127806,131902,137195,'previous'),133729.3,'2025 old-rule counterfactual');
near(weightedEnrolment(127806,131902,137195,'current'),135607.1,'2025 current rule');
near(weightedEnrolment(127806,131902,137195,'projection'),137195,'projection-only sensitivity');
near(weightedEnrolment(100,100,100,'previous'),100,'stable enrolment');
near(weightedEnrolment(100,100,100,'current'),100,'stable enrolment');

const projects=[
  {approved:'2020-06',plannedOpening:'2022-09',actualOpening:'2023-09',places:100},
  {approved:'2020-06',plannedOpening:'2024-09',actualOpening:'2024-09',places:200},
];
const unchanged=constructionTimeline(projects,0);
assert.ok(unchanged.rows.every(r=>r.actual===r.scenario));
near(unchanged.scheduleMaeMonths,6,'known project schedule errors');
near(constructionTimeline(projects,-12).placeMonthsDifference,3600,'12-month earlier availability');
near(constructionTimeline(projects,12).placeMonthsDifference,-3600,'12-month later availability');
assert.ok(constructionTimeline(projects,12).rows.every(r=>r.scenario<=r.actual),'delays cannot increase cumulative capacity');

const consolidated=JSON.parse(await readFile(new URL('capacity-data.json',root),'utf8'));
validateCapacityData(consolidated);
assert.deepEqual(consolidated.workforce.history,rn.history,'consolidation preserves CIHI source records');
const full=simulateCapacity(consolidated,{});
near(full.funding.selected,135607.1,'consolidated default funding');
near(full.funding.gapToObserved,2754.1,'weighted estimate gap to realized eligible FTE');
near(full.funding.validation.forecast.mae,3000+1/3,'published CBE forecast MAE');
near(full.funding.validation.persistence.mae,4066+1/3,'CBE no-growth forecast MAE');
near(full.construction.totalPlaces,4800,'five-project approved places');
near(full.construction.scheduleMaeMonths,4,'five-project schedule MAE');
assert.deepEqual(full.construction.projects.map(r=>r.scheduleErrorMonths),[0,0,1,7,-12]);
near(simulateCapacity(consolidated,{openingShiftMonths:12}).construction.placeMonthsDifference,-57600,'cohort 12-month delay');
near(simulateCapacity(consolidated,{fundingYear:2023,fundingRule:'current'}).funding.differenceFromHistoricalRule,2520.8,'2023 rule-only counterfactual');
near(simulateCapacity(consolidated,{fundingYear:2025,fundingRule:'previous'}).funding.differenceFromHistoricalRule,-1877.8,'2025 rule-only counterfactual');
near(simulateCapacity(consolidated,{fundingYear:2025,fundingRule:'projection'}).funding.selected,137195,'projection-only reference');
for(const [label,mutate] of [
  ['missing year',d=>d.workforce.history.splice(2,1)],
  ['duplicate year',d=>d.workforce.history[2].year=2017],
  ['non-finite stock',d=>d.workforce.history[2].supply=Infinity],
  ['missing stock',d=>d.workforce.history[2].supply=null],
  ['latest outflow unavailable',d=>d.workforce.history.at(-1).outflow=0],
  ['negative outflow',d=>d.workforce.history[2].outflow=-1],
  ['invalid source',d=>d.workforce.history[2].sourceId='missing'],
  ['negative eligible FTE',d=>d.schools.funding.vintages[0].forecast=-1],
  ['non-finite eligible FTE',d=>d.schools.funding.vintages[0].forecast=NaN],
  ['forecast after outcome',d=>d.schools.funding.vintages[0].vintageDate='2024-01-01'],
  ['inconsistent prior observation',d=>d.schools.funding.vintages[0].currentActualAtBudget=999],
  ['negative project places',d=>d.schools.construction.projects[0].approvedCapacity=-1],
  ['post-opening approval',d=>d.schools.construction.projects[0].constructionApprovalDate='2030-01'],
  ['post-outcome plan',d=>d.schools.construction.projects[0].planVintageDate='2030-01'],
]) {
  const bad=structuredClone(consolidated);mutate(bad);
  assert.throws(()=>validateCapacityData(bad),undefined,label);
}
assert.throws(()=>constructionTimeline(projects,NaN));
assert.throws(()=>constructionTimeline(projects,Infinity));
console.log(JSON.stringify({status:'passed',scope:'source observations, holdout leakage, equal-origin baselines, closed-form scenario, funding fixtures, timing invariants, consolidated adapter, invalid-data guards',holdout:metrics(predicted),linearDriftMAE:2608.7,cbeForecastMAE:3000+1/3,constructionScheduleMAEMonths:4}));
